13	const BASE_SCORE = 1;
14	const MINIMUM_BONUS = 1;
15	const POINTS_PER_EXTRA_TYPE = 2;
16	const TYPES_INCLUDED_IN_MINIMUM_BONUS = 3;
17	
18	const varietyBonusFor = (otherTypeCount: number): number =>
19	  Math.max(
20	    MINIMUM_BONUS,
21	    POINTS_PER_EXTRA_TYPE * (otherTypeCount - TYPES_INCLUDED_IN_MINIMUM_BONUS),
22	  );
