const cardsSeenBy = (army: Card[], scorerIndex: number): Card[] =>
  army.filter((_, index) => index !== scorerIndex);

const scoreSphinxSeeing = (visibleCards: Card[]): number =>
  BASE_SCORE + varietyBonusFor(countDistinctTypes(visibleCards));

export const scoreArmy = (army: Card[]): number =>
  army.reduce(
    (total, card, index) =>
      isSphinx(card)
        ? total + scoreSphinxSeeing(cardsSeenBy(army, index))
        : total,
    0,
  );
